use super::{connect,sqlite::Transaction,tasks::{TaskError,TaskOwner},StorageError};
use serde::Serialize;
use std::path::Path;
#[derive(Debug,Serialize)]
#[serde(rename_all="camelCase")]
pub struct Event { pub id:String,pub title:String,pub details:String,pub event_date:String,pub start_time:Option<String>,pub end_time:Option<String>,pub revision:i64,pub created_at:String,pub updated_at:String }
fn id(s:&str)->bool{s.len()==32&&s!="00000000000000000000000000000000"&&s.bytes().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase())}
fn date(s:&str)->bool{let p:Vec<_>=s.split('-').collect();if p.len()!=3||p[0].len()!=4||p[1].len()!=2||p[2].len()!=2{return false}let(Ok(y),Ok(m),Ok(d))=(p[0].parse::<u32>(),p[1].parse::<u32>(),p[2].parse::<u32>())else{return false};let leap=y%4==0&&(y%100!=0||y%400==0);let max=match m{1|3|5|7|8|10|12=>31,4|6|9|11=>30,2 if leap=>29,2=>28,_=>return false};d>0&&d<=max}
fn time(s:&str)->bool{let p:Vec<_>=s.split(':').collect();p.len()==2&&p[0].len()==2&&p[1].len()==2&&p[0].parse::<u8>().is_ok_and(|h|h<24)&&p[1].parse::<u8>().is_ok_and(|m|m<60)}
fn valid(title:&str,details:&str,day:&str,start:Option<&str>,end:Option<&str>)->bool{!title.is_empty()&&title.chars().count()<=200&&!title.chars().any(char::is_control)&&details.chars().count()<=5000&&!details.chars().any(|c|c.is_control()&&!matches!(c,'\n'|'\r'|'\t'))&&date(day)&&start.is_none_or(time)&&end.is_none_or(time)&&(end.is_none()||start.is_some_and(|s|end.is_some_and(|e|e>s)))}
const FIELDS:&str="id,title,details,event_date,COALESCE(start_time,''),COALESCE(end_time,''),revision,created_at,updated_at";
fn decode(r:Vec<String>)->Result<Event,TaskError>{if r.len()!=9||!id(&r[0]){return Err(StorageError::InvalidSchema.into())}let revision=r[6].parse().map_err(|_|StorageError::InvalidSchema)?;let start=(!r[4].is_empty()).then_some(r[4].as_str());let end=(!r[5].is_empty()).then_some(r[5].as_str());if revision<1||!valid(&r[1],&r[2],&r[3],start,end){return Err(StorageError::InvalidSchema.into())}Ok(Event{id:r[0].clone(),title:r[1].clone(),details:r[2].clone(),event_date:r[3].clone(),start_time:start.map(str::to_owned),end_time:end.map(str::to_owned),revision,created_at:r[7].clone(),updated_at:r[8].clone()})}
fn get(db:&super::sqlite::Connection,owner:&TaskOwner,key:&str)->Result<Event,TaskError>{let mut rows=db.query(&format!("SELECT {FIELDS} FROM calendar_events WHERE id=?1 AND project_ref=?2 AND user_id=?3"),&[key,&owner.project_ref,&owner.user_id])?;decode(rows.pop().ok_or(TaskError::NotFound)?)}
pub fn list(path:&Path,owner:&TaskOwner,from:&str,to:&str)->Result<Vec<Event>,TaskError>{owner.validate()?;if !date(from)||!date(to)||from>to{return Err(TaskError::InvalidInput)}let(db,_)=connect(path)?;db.query(&format!("SELECT {FIELDS} FROM calendar_events WHERE project_ref=?1 AND user_id=?2 AND event_date>=?3 AND event_date<=?4 ORDER BY event_date,start_time,id LIMIT 500"),&[&owner.project_ref,&owner.user_id,from,to])?.into_iter().map(decode).collect()}
pub fn create(path:&Path,owner:&TaskOwner,key:&str,title:&str,details:&str,day:&str,start:Option<&str>,end:Option<&str>)->Result<Event,TaskError>{owner.validate()?;let title=title.trim();if !id(key)||!valid(title,details,day,start,end){return Err(TaskError::InvalidInput)}let(db,_)=connect(path)?;let tx=Transaction::begin(&db)?;db.query("INSERT INTO calendar_events(id,project_ref,user_id,title,details,event_date,start_time,end_time) VALUES(?1,?2,?3,?4,?5,?6,NULLIF(?7,''),NULLIF(?8,'')) ON CONFLICT(id) DO NOTHING",&[key,&owner.project_ref,&owner.user_id,title,details,day,start.unwrap_or(""),end.unwrap_or("")])?;let event=get(&db,owner,key).map_err(|e|if e==TaskError::NotFound{TaskError::Conflict}else{e})?;if event.title!=title||event.details!=details||event.event_date!=day||event.start_time.as_deref()!=start||event.end_time.as_deref()!=end{return Err(TaskError::Conflict)}tx.commit()?;Ok(event)}
pub fn save(path:&Path,owner:&TaskOwner,key:&str,expected:i64,title:&str,details:&str,day:&str,start:Option<&str>,end:Option<&str>)->Result<Event,TaskError>{owner.validate()?;let title=title.trim();if !id(key)||expected<1||!valid(title,details,day,start,end){return Err(TaskError::InvalidInput)}let(db,_)=connect(path)?;let tx=Transaction::begin(&db)?;let old=get(&db,owner,key)?;let same=old.title==title&&old.details==details&&old.event_date==day&&old.start_time.as_deref()==start&&old.end_time.as_deref()==end;if same&&(old.revision==expected||expected.checked_add(1)==Some(old.revision)){tx.commit()?;return Ok(old)}if old.revision!=expected{return Err(TaskError::Conflict)}db.query("UPDATE calendar_events SET title=?4,details=?5,event_date=?6,start_time=NULLIF(?7,''),end_time=NULLIF(?8,''),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=?1 AND project_ref=?2 AND user_id=?3 AND revision=?9",&[key,&owner.project_ref,&owner.user_id,title,details,day,start.unwrap_or(""),end.unwrap_or(""),&expected.to_string()])?;let event=get(&db,owner,key)?;tx.commit()?;Ok(event)}
pub fn delete(path:&Path,owner:&TaskOwner,key:&str,expected:i64)->Result<(),TaskError>{owner.validate()?;if !id(key)||expected<1{return Err(TaskError::InvalidInput)}let(db,_)=connect(path)?;let tx=Transaction::begin(&db)?;let rows=db.query("SELECT revision FROM calendar_events WHERE id=?1 AND project_ref=?2 AND user_id=?3",&[key,&owner.project_ref,&owner.user_id])?;if let Some(row)=rows.first(){if row[0]!=expected.to_string(){return Err(TaskError::Conflict)}db.query("DELETE FROM calendar_events WHERE id=?1 AND project_ref=?2 AND user_id=?3",&[key,&owner.project_ref,&owner.user_id])?;}tx.commit()?;Ok(())}

pub fn get_record(path:&Path,owner:&TaskOwner,key:&str)->Result<Event,TaskError>{owner.validate()?;if !id(key){return Err(TaskError::InvalidInput)}let(db,_)=connect(path)?;get(&db,owner,key)}

pub fn overlaps(path:&Path,owner:&TaskOwner,key:&str,day:&str,start:&str,end:&str)->Result<u64,TaskError>{
 owner.validate()?;if (!key.is_empty()&&!id(key))||!date(day)||!time(start)||!time(end)||start>=end{return Err(TaskError::InvalidInput)}
 let(db,_)=connect(path)?;let rows=db.query("SELECT COUNT(*) FROM calendar_events WHERE project_ref=?1 AND user_id=?2 AND id<>?3 AND event_date=?4 AND start_time<?6 AND end_time>?5",&[&owner.project_ref,&owner.user_id,key,day,start,end])?;
 rows.first().and_then(|r|r.first()).ok_or(StorageError::InvalidSchema)?.parse().map_err(|_|StorageError::InvalidSchema.into())
}
